public class NumMatrix{int m,n;int[][]b,a;void Add(int r,int c,int d){for(int i=r+1;i<=m;i+=i&-i)for(int j=c+1;j<=n;j+=j&-j)b[i][j]+=d;}int Sum(int r,int c){int x=0;for(int i=r+1;i>0;i-=i&-i)for(int j=c+1;j>0;j-=j&-j)x+=b[i][j];return x;}public NumMatrix(int[][]x){m=x.Length;n=m>0?x[0].Length:0;b=new int[m+1][];a=new int[m][];for(int i=0;i<=m;i++)b[i]=new int[n+1];for(int i=0;i<m;i++){a[i]=new int[n];for(int j=0;j<n;j++)Update(i,j,x[i][j]);}}public void Update(int r,int c,int v){int d=v-a[r][c];a[r][c]=v;Add(r,c,d);}public int SumRegion(int r1,int c1,int r2,int c2)=>Sum(r2,c2)-Sum(r1-1,c2)-Sum(r2,c1-1)+Sum(r1-1,c1-1);}
